function bm_can_write(array $u):bool{if(($u['role']??'')==='Super Admin')return true;if(tt_user_can_open_module($u,'Directors'))return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function bm_date(string $v,string $label,bool $optional=false):string{$v=trim($v);if($optional&&$v==='')return '';if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v))bm_out(['ok'=>false,'error'=>$label.' is invalid.'],422);return $v;}
