elseif($action==='save_wht_rate'){$rate=bm_num($b['whtPercent']??0,'Brokerage withholding %',true);if($rate>100)bm_out(['ok'=>false,'error'=>'Brokerage withholding % cannot exceed 100.'],422);$from=bm_date((string)($b['effectiveFrom']??''),'Effective From');$to=bm_date((string)($b['effectiveTo']??''),'Effective To',true);if($to!==''&&$to<$from)bm_out(['ok'=>false,'error'=>'Effective To cannot be before Effective From.'],422);$id='BWHT-'.substr(hash('sha256',$from),0,16);$s['brokerageMaster']['whtRates'][$id]=['id'=>$id,'whtPercent'=>$rate,'effectiveFrom'=>$from,'effectiveTo'=>$to,'active'=>(bool)($b['active']??true),'updatedAt'=>gmdate('c'),'updatedBy'=>$who];}
